sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading) {
      return;
   }
   if(newValue == ''){
	g_form.clearValue('employee_email');
	g_form.clearValue('department');
	return;
   }
	var ga = new GlideAjax('CallerDetailsAjax');
	ga.addParam('sysparm_name', 'getUserInfo');
	ga.addParam('sysparm_user_id', newValue);
   ga.getXMLAnswer(function(response){
	if(response){
	var data = JSON.parse(response);
	g_form.setValue('employee_email', data.email);
    g_form.setValue('department', data.department_id, data.department_name);
        }
   });
}
